{
  "name": "Modbus RTU串口网关",
  "name_en": "Modbus RTU Serial Gateway",
  "manufacturer": "",
  "description": "一种通过串口总线（常见为 RS-485）与 Modbus RTU 从站设备通信的工业网关或接口设备。在实验室中常用于把上位机、服务器或控制系统连接到仪表、控制器、远程 I/O 模块和传感器，实现串行现场总线上的数据转发与设备接入。",
  "description_en": "An industrial gateway or interface device that communicates with Modbus RTU slave devices over a serial bus, commonly RS-485. In laboratories, it is used to connect a host computer, server, or control system to instruments, controllers, remote I/O modules, and sensors, enabling data exchange and device integration on a serial fieldbus.",
  "actions": [
    {
      "action_name": "auto-loop",
      "description": "处理排队的 Modbus RTU 串口收发循环",
      "description_en": "process the queued Modbus RTU serial request-response cycle"
    },
    {
      "action_name": "auto-srv_engine_entry",
      "description": "提交服务器侧 Modbus 请求到串口总线并等待响应",
      "description_en": "submit a server-side Modbus request to the serial bus and wait for the response"
    }
  ],
  "tag_hints": [
    "Modbus RTU",
    "RS-485 serial communication",
    "industrial gateway",
    "fieldbus integration",
    "instrument networking"
  ]
}

